f5-animate.source:
flowchart TD
     A e1@--> B
     C e2@--> D
     E e3@--> F
    e1@{ animate: true }
    e2@{ animate: false }
    e3@{ animate: true }
    e3@{ animate: false }

f5-animate-false.source:
flowchart TD
     A e1@--> B
    e1@{ animate: false }

st5-composite-plain.source:
stateDiagram-v2
      [*] --> NotShooting

      state NotShooting {
        Idle --> Configuring : EvConfig
      }

      note right of NotShooting : This is a note on a composite state

st5-composite-start.source:
stateDiagram-v2
      state "Not Shooting State" as NotShooting {
        state "Idle mode" as Idle
        [*] --> Idle
      }
      note right of NotShooting : note
